1	// Package handler implements gin HTTP handlers for the workspace API routes.
2	package handler
3	
4	import (
5		"context"
6		"net/http"
7		"strconv"
8	
9		"github.com/gin-gonic/gin"
10	
11		"github.com/tiendv89/workflow-backend/internal/domain"
12	)
13	
14	// Service is the interface the handler depends on.
15	type Service interface {
16		ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error)
17		ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceDetail, domain.SourceError)
18		GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError)
19		SearchFeatures(ctx context.Context, workspaceID string, query domain.FeatureSearchQuery) (*domain.PagedFeatures, domain.SourceError)
20		SearchTasks(ctx context.Context, workspaceID, featureID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError)
21		SearchWorkspaceTasks(ctx context.Context, workspaceID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError)
22		GetWorkspaceTask(ctx context.Context, workspaceID, taskID string) (*domain.TaskDetail, domain.SourceError)
23		SyncWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError)
24		GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, domain.SourceError)
25		GetTask(ctx context.Context, workspaceID, featureID, taskID string) (*domain.TaskDetail, domain.SourceError)
26		ListActivity(ctx context.Context, workspaceID string, scope domain.ActivityScope) ([]domain.ActivityEvent, domain.SourceError)
27	}
28	
29	// WorkspaceHandler holds a reference to the source service.
