	featureID := c.Param("featureId")
	taskID := c.Param("taskId")
	detail, se := h.svc.GetTask(c.Request.Context(), workspaceID, featureID, taskID)
	if se != (domain.SourceError{}) {
		respondSourceError(c, se, nil)
		return
	}
	respondOK(c, detail)
}

// ListActivity godoc
// GET /api/workspaces/:workspaceId/activity
func (h *WorkspaceHandler) ListActivity(c *gin.Context) {
	workspaceID := c.Param("workspaceId")
	scope := domain.ActivityScope{
		FeatureID: c.Query("featureId"),
		TaskID:    c.Query("taskId"),
	}
	events, se := h.svc.ListActivity(c.Request.Context(), workspaceID, scope)
	if se != (domain.SourceError{}) {
		respondSourceError(c, se, nil)
		return
	}
	respondOK(c, events)
}

// --- error response helpers ---

type apiSuccessResponse struct {
	Success bool        `json:"success"`
	Data    interface{} `json:"data"`
}

type apiErrorResponse struct {
	Success bool          `json:"success"`
	Error   *apiErrorBody `json:"error"`
}

type apiErrorBody struct {
	Code       domain.ErrorCode   `json:"code"`
	Message    string             `json:"message"`
	Source     domain.ErrorSource `json:"source"`
	Retryable  bool               `json:"retryable"`
	Path       string             `json:"path,omitempty"`
	CachedData interface{}        `json:"cached_data,omitempty"`
}

func respondOK(c *gin.Context, data interface{}) {
	c.JSON(http.StatusOK, apiSuccessResponse{
		Success: true,
		Data:    data,
	})
}

func respondError(c *gin.Context, err error) {
	if se, ok := err.(domain.SourceError); ok {
		respondSourceError(c, se, nil)
		return
	}
	respondSourceError(c, domain.SourceError{
		Code:      domain.ErrAdapterInternal,
		Message:   err.Error(),
		Source:    domain.ErrorSourceAdapter,
		Retryable: true,
	}, nil)
}

func parsePagination(c *gin.Context) (int, int, bool) {
	page := 1
	if rawPage := c.Query("page"); rawPage != "" {
		parsed, err := strconv.Atoi(rawPage)
		if err != nil {
			respondSourceError(c, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be an integer"), nil)
			return 0, 0, false
		}
		if parsed < 1 {
			respondSourceError(c, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1"), nil)
			return 0, 0, false
		}
		page = parsed
	}

	limit := 0
	if rawLimit := c.Query("limit"); rawLimit != "" {
		parsed, err := strconv.Atoi(rawLimit)
		if err != nil {
			respondSourceError(c, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be an integer"), nil)
			return 0, 0, false
		}
		limit = parsed
	}
	return page, limit, true
}

func respondSourceError(c *gin.Context, se domain.SourceError, cachedData interface{}) {
	statusCode := sourceErrorHTTPStatus(se)
	errBody := &apiErrorBody{
		Code:      se.Code,
		Message:   se.Message,
		Source:    se.Source,
		Retryable: se.Retryable,
		Path:      se.Path,
	}
	if cachedData != nil {
		errBody.CachedData = cachedData
	}
	c.JSON(statusCode, apiErrorResponse{
		Success: false,
		Error:   errBody,
	})
}

func sourceErrorHTTPStatus(se domain.SourceError) int {
	switch se.Code {
	case domain.ErrDatabaseNotFound, domain.ErrGitHubNotFound:
		return http.StatusNotFound
	case domain.ErrValidationInvalidURL, domain.ErrValidationMissingInput, domain.ErrValidationInvalidQuery:
		return http.StatusBadRequest
	case domain.ErrGitHubUnauthorized:
		return http.StatusUnauthorized
	case domain.ErrGitHubRateLimit:
		return http.StatusTooManyRequests
	case domain.ErrAdapterTimeout:
		return http.StatusGatewayTimeout
	default:
		return http.StatusInternalServerError
	}
}

package domain

import "fmt"

// ErrorSource identifies the system that produced a SourceError.
type ErrorSource string

const (
	ErrorSourceGitHub     ErrorSource = "github"
	ErrorSourceDatabase   ErrorSource = "database"
	ErrorSourceParser     ErrorSource = "parser"
	ErrorSourceAdapter    ErrorSource = "adapter"
	ErrorSourceValidation ErrorSource = "validation"
)

// ErrorCode is a machine-readable error identifier.
type ErrorCode string

const (
	ErrGitHubRateLimit    ErrorCode = "GITHUB_RATE_LIMIT"
	ErrGitHubNotFound     ErrorCode = "GITHUB_NOT_FOUND"
	ErrGitHubUnauthorized ErrorCode = "GITHUB_UNAUTHORIZED"
	ErrGitHubNetworkError ErrorCode = "GITHUB_NETWORK_ERROR"
	ErrGitHubServerError  ErrorCode = "GITHUB_SERVER_ERROR"

	ErrDatabaseConnection  ErrorCode = "DATABASE_CONNECTION"
	ErrDatabaseQuery       ErrorCode = "DATABASE_QUERY"
	ErrDatabaseTransaction ErrorCode = "DATABASE_TRANSACTION"
	ErrDatabaseNotFound    ErrorCode = "DATABASE_NOT_FOUND"

	ErrAdapterInternal ErrorCode = "ADAPTER_INTERNAL"
	ErrAdapterTimeout  ErrorCode = "ADAPTER_TIMEOUT"

	ErrValidationInvalidURL   ErrorCode = "VALIDATION_INVALID_URL"
	ErrValidationMissingInput ErrorCode = "VALIDATION_MISSING_INPUT"
	ErrValidationInvalidQuery ErrorCode = "VALIDATION_INVALID_QUERY"
)

// SourceError is the normalized error shape for all backend errors.
type SourceError struct {
	Code      ErrorCode   `json:"code"`
	Message   string      `json:"message"`
	Source    ErrorSource `json:"source"`
	Retryable bool        `json:"retryable"`
	Path      string      `json:"path,omitempty"`
}

func (e SourceError) Error() string {
	if e.Path != "" {
		return fmt.Sprintf("[%s/%s] %s (path: %s)", e.Source, e.Code, e.Message, e.Path)
	}
	return fmt.Sprintf("[%s/%s] %s", e.Source, e.Code, e.Message)
}

// APIError is the HTTP response body for error responses.
type APIError struct {
	Code       ErrorCode   `json:"code"`
	Message    string      `json:"message"`
	Source     ErrorSource `json:"source"`
	Retryable  bool        `json:"retryable"`
	CachedData interface{} `json:"cached_data,omitempty"`
}

// NewDatabaseNotFound returns a SourceError for missing rows.
func NewDatabaseNotFound(resource, id string) SourceError {
	return SourceError{
		Code:      ErrDatabaseNotFound,
		Message:   fmt.Sprintf("%s not found: %s", resource, id),
		Source:    ErrorSourceDatabase,
		Retryable: false,
	}
}

// NewDatabaseError returns a SourceError for database failures.
func NewDatabaseError(code ErrorCode, detail string) SourceError {
	return SourceError{
		Code:      code,
		Message:   fmt.Sprintf("Database error: %s", detail),
		Source:    ErrorSourceDatabase,
		Retryable: true,
	}
}

// NewAdapterError returns a SourceError for adapter-service failures.
func NewAdapterError(code ErrorCode, detail string) SourceError {
	return SourceError{
		Code:      code,
		Message:   fmt.Sprintf("Adapter service error: %s", detail),
		Source:    ErrorSourceAdapter,
		Retryable: true,
	}
}

// NewValidationError returns a SourceError for input validation failures.
func NewValidationError(code ErrorCode, message string) SourceError {
	return SourceError{
		Code:      code,
		Message:   message,
		Source:    ErrorSourceValidation,
		Retryable: false,
	}
}

// FromSourceError converts a SourceError to an APIError with optional cached data.
func FromSourceError(e SourceError, cachedData interface{}) APIError {
	return APIError{
		Code:       e.Code,
		Message:    e.Message,
		Source:     e.Source,
		Retryable:  e.Retryable,
		CachedData: cachedData,
	}
}

