116	func (s *WorkspaceService) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceDetail, domain.SourceError) {
117		workspaceID, err := s.adapter.ImportWorkspace(ctx, adapter.ImportRequest{
