325		}
326	
327		return &domain.FeatureDetail{
328			FeatureSummary: domain.FeatureSummary{
329				ID:           database.UUIDString(feat.ID),
330				FeatureID:    database.UUIDString(feat.FeatureID),
331				FeatureName:  feat.FeatureName,
332				Title:        feat.Title,
333				Status:       derefStr(feat.FeatureStatus),
334				CurrentStage: derefStr(feat.CurrentStage),
335				Stages:       rawJSONOrNil(feat.Stages),
336				UpdatedAt:    feat.UpdatedAt.Time,
337				TaskCounts:   counts,
338			},
339			WorkspaceID: workspaceID,
340			Documents:   docLinks,
341			Tasks:       taskSummaries,
342			Activity:    activityEvents,
343			SourceState: ss,
