472	
473		filters := database.FeatureSearchFilters{
474			Title:  query.Title,
475			Status: query.Status,
476			Sort:   query.Sort,
477			Page:   query.Page,
478			Limit:  query.Limit,
479		}
480		features, err := s.db.SearchWorkspaceFeatures(ctx, workspaceID, filters)
481		if err != nil {
482			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
483		}
484	
485		total, err := s.db.CountWorkspaceFeatures(ctx, workspaceID, filters)
486		if err != nil {
487			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
488		}
489	
490		taskCountsByFeature := map[string]domain.TaskCounts{}
491		if len(features) > 0 {
492			countRows, err := s.db.ListFeatureTaskCounts(ctx, workspaceID, featureIDs(features))
493			if err != nil {
494				return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
495			}
496			taskCountsByFeature = taskCountsFromRows(countRows)
497		}
498	
499		items := make([]domain.FeatureSummary, 0, len(features))
500		for _, f := range features {
501			counts := taskCountsByFeature[database.UUIDString(f.FeatureID)]
502			items = append(items, domain.FeatureSummary{
503				ID:           database.UUIDString(f.ID),
504				FeatureID:    database.UUIDString(f.FeatureID),
505				FeatureName:  f.FeatureName,
506				Title:        f.Title,
507				Status:       derefStr(f.FeatureStatus),
508				CurrentStage: derefStr(f.CurrentStage),
509				Stages:       rawJSONOrNil(f.Stages),
510				UpdatedAt:    f.UpdatedAt.Time,
511				TaskCounts:   counts,
512			})
513		}
514		return &domain.PagedFeatures{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
515	}
516	
517	// GetTask returns full task detail including activity.
518	func (s *WorkspaceService) GetTask(ctx context.Context, workspaceID, featureID, taskID string) (*domain.TaskDetail, domain.SourceError) {
519		ws, err := s.db.GetWorkspace(ctx, workspaceID)
520		if err != nil {
521			if errors.Is(err, database.ErrNotFound) {
522				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
523			}
524			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
525		}
526		wsID := database.UUIDString(ws.ID)
527	
528		feat, err := s.db.GetWorkspaceFeature(ctx, wsID, featureID)
529		if err != nil {
530			if errors.Is(err, database.ErrNotFound) {
531				return nil, domain.NewDatabaseNotFound("feature", featureID)
532			}
533			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
534		}
535	
536		t, err := s.db.GetWorkspaceTask(ctx, wsID, database.UUIDString(feat.FeatureID), taskID)
537		if err != nil {
538			if errors.Is(err, database.ErrNotFound) {
539				return nil, domain.NewDatabaseNotFound("task", taskID)
540			}
541			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
542		}
543	
544		activity, err := s.db.ListActivityEvents(ctx, wsID, database.UUIDString(t.FeatureID), database.UUIDString(t.TaskID))
545		if err != nil {
546			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
547		}
548	
549		return taskDetailFromRow(workspaceID, t, activity), domain.SourceError{}
550	}
551	
552	// GetWorkspaceTask returns full task detail for a task in a workspace.
553	func (s *WorkspaceService) GetWorkspaceTask(ctx context.Context, workspaceID, taskID string) (*domain.TaskDetail, domain.SourceError) {
554		ws, err := s.db.GetWorkspace(ctx, workspaceID)
555		if err != nil {
556			if errors.Is(err, database.ErrNotFound) {
557				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
558			}
559			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
560		}
561		wsID := database.UUIDString(ws.ID)
562	
563		t, err := s.db.GetWorkspaceTaskByID(ctx, wsID, taskID)
564		if err != nil {
565			if errors.Is(err, database.ErrNotFound) {
566				return nil, domain.NewDatabaseNotFound("task", taskID)
567			}
568			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
569		}
570	
571		activity, err := s.db.ListActivityEvents(ctx, wsID, database.UUIDString(t.FeatureID), database.UUIDString(t.TaskID))
572		if err != nil {
573			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
574		}
575	
576		return taskDetailFromRow(workspaceID, t, activity), domain.SourceError{}
577	}
578	
579	func taskDetailFromRow(workspaceID string, t database.WorkspaceTask, activity []database.WorkspaceActivityEvent) *domain.TaskDetail {
580		activityEvents := make([]domain.ActivityEvent, 0, len(activity))
581		for _, a := range activity {
582			activityEvents = append(activityEvents, toActivityEvent(a))
583		}
584	
585		var dependsOn []string
586		if t.DependsOn != nil {
587			_ = json.Unmarshal(t.DependsOn, &dependsOn)
588		}
589		if dependsOn == nil {
590			dependsOn = []string{}
591		}
592	
593		var execution map[string]interface{}
594		if t.Execution != nil {
595			_ = json.Unmarshal(t.Execution, &execution)
596		}
597		execCtx := domain.ExecutionContext{}
598		if execution != nil {
599			if v, ok := execution["actor_type"].(string); ok {
600				execCtx.ActorType = v
601			}
602			if v, ok := execution["last_updated_by"].(string); ok {
603				execCtx.LastUpdatedBy = v
604			}
605			if v, ok := execution["last_updated_at"].(string); ok {
606				execCtx.LastUpdatedAt = v
607			}
608		}
609	
610		summary := toTaskSummary(t)
611		prRefs := parsePRRefs(t.Pr, t.WorkspacePr, summary.Repo)
612		return &domain.TaskDetail{
613			ID:            summary.ID,
614			TaskID:        summary.TaskID,
615			TaskName:      summary.TaskName,
616			FeatureID:     summary.FeatureID,
617			FeatureName:   summary.FeatureName,
618			Title:         summary.Title,
619			Status:        summary.Status,
620			Repo:          summary.Repo,
621			Branch:        summary.Branch,
622			NextAction:    summary.NextAction,
623			IsBlocked:     summary.IsBlocked,
624			BlockedReason: summary.BlockedReason,
625			WorkspaceID:   workspaceID,
626			DependsOn:     dependsOn,
627			Execution:     execCtx,
628			PRRefs:        prRefs,
629			Activity:      activityEvents,
630		}
631	}
632	
633	// ListActivity returns activity events for a workspace.
634	func (s *WorkspaceService) ListActivity(ctx context.Context, workspaceID string, scope domain.ActivityScope) ([]domain.ActivityEvent, domain.SourceError) {
635		ws, err := s.db.GetWorkspace(ctx, workspaceID)
636		if err != nil {
637			if errors.Is(err, database.ErrNotFound) {
638				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
639			}
640			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
641		}
642		wsID := database.UUIDString(ws.ID)
643	
644		events, err := s.db.ListActivityEvents(ctx, wsID, scope.FeatureID, scope.TaskID)
645		if err != nil {
646			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
647		}
648	
649		out := make([]domain.ActivityEvent, 0, len(events))
650		for _, a := range events {
651			out = append(out, toActivityEvent(a))
652		}
653		return out, domain.SourceError{}
654	}
655	
656	// githubRepoURL fetches the GitHub repo URL for a workspace from workspace_github_sources.
657	func (s *WorkspaceService) githubRepoURL(ctx context.Context, workspaceID string) string {
658		src, err := s.db.GetGitHubSource(ctx, workspaceID)
659		if err != nil {
660			return ""
661		}
662		return src.RepoURL
663	}
664	
665	// --- conversion helpers ---
666	
667	func toSourceState(run *database.WorkspaceSyncRun, threshold time.Duration) domain.SourceState {
668		if run == nil {
669			return domain.DeriveSourceState(nil, threshold)
670		}
671		sr := &domain.SyncRun{
672			ID:          database.UUIDString(run.ID),
673			WorkspaceID: database.UUIDString(run.WorkspaceID),
674			Trigger:     run.Trigger,
675			Mode:        run.Mode,
676			Status:      domain.SyncStatus(run.Status),
677			StartedAt:   run.StartedAt.Time,
678		}
679		if run.FinishedAt.Valid {
680			t := run.FinishedAt.Time
681			sr.FinishedAt = &t
682		}
683		if run.CommitSha != nil {
684			sr.CommitSHA = *run.CommitSha
685		}
686		if run.ErrorCode != nil {
687			sr.ErrorCode = *run.ErrorCode
688		}
689		if run.ErrorMessage != nil {
690			sr.ErrorMsg = *run.ErrorMessage
691		}
692		return domain.DeriveSourceState(sr, threshold)
693	}
694	
695	func toTaskSummary(t database.WorkspaceTask) domain.TaskSummary {
696		isBlocked := t.Status != nil && *t.Status == "blocked"
697		return domain.TaskSummary{
698			ID:            database.UUIDString(t.ID),
699			TaskID:        database.UUIDString(t.TaskID),
700			TaskName:      t.TaskName,
701			FeatureID:     database.UUIDString(t.FeatureID),
702			FeatureName:   t.FeatureName,
703			Title:         t.Title,
704			Status:        derefStr(t.Status),
705			Repo:          derefStr(t.Repo),
706			Branch:        derefStr(t.Branch),
707			IsBlocked:     isBlocked,
708			BlockedReason: derefStr(t.BlockedReason),
709			Pr:            rawJSONOrNil(t.Pr),
710			WorkspacePr:   rawJSONOrNil(t.WorkspacePr),
711		}
712	}
713	
714	func toActivityEvent(a database.WorkspaceActivityEvent) domain.ActivityEvent {
715		e := domain.ActivityEvent{
716			Action:    derefStr(a.Action),
717			Scope:     a.ScopeType,
718			Actor:     derefStr(a.Actor),
719			Note:      derefStr(a.Note),
720			FeatureID: database.UUIDString(a.FeatureID),
721			TaskID:    database.UUIDString(a.TaskID),
722		}
723		if a.OccurredAt != nil {
724			if t, err := time.Parse(time.RFC3339, *a.OccurredAt); err == nil {
725				e.OccurredAt = t
726			}
727		}
728		return e
729	}
730	
731	func isValidSearchSort(sort string) bool {
732		switch sort {
733		case "title_asc", "title_desc", "status_asc", "status_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
734			return true
735		default:
736			return false
737		}
738	}
739	
740	func isValidTaskSearchSort(sort string) bool {
741		switch sort {
742		case "task_id_asc", "task_id_desc", "title_asc", "title_desc", "status_asc", "status_desc", "repo_asc", "repo_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
743			return true
744		default:
745			return false
746		}
747	}
748	
749	func featureIDs(features []database.WorkspaceFeature) []string {
750		ids := make([]string, 0, len(features))
751		for _, feature := range features {
752			ids = append(ids, database.UUIDString(feature.FeatureID))
753		}
754		return ids
755	}
756	
757	func taskCountsFromRows(rows []database.WorkspaceFeatureTaskCounts) map[string]domain.TaskCounts {
758		counts := make(map[string]domain.TaskCounts, len(rows))
759		for _, row := range rows {
760			counts[database.UUIDString(row.FeatureID)] = domain.TaskCounts{
761				Total:      int(row.Total),
762				Done:       int(row.Done),
763				InProgress: int(row.InProgress),
764				Blocked:    int(row.Blocked),
765				Ready:      int(row.Ready),
766				Todo:       int(row.Todo),
767			}
768		}
769		return counts
770	}
771	
772	func countTasksByFeature(tasks []database.WorkspaceTask) map[string]domain.TaskCounts {
773		counts := make(map[string]domain.TaskCounts, len(tasks))
774		for _, t := range tasks {
775			featureID := database.UUIDString(t.FeatureID)
776			current := counts[featureID]
777			current.Total++
778			if t.Status != nil {
779				switch *t.Status {
780				case "done":
781					current.Done++
782				case "in_progress":
783					current.InProgress++
784				case "blocked":
785					current.Blocked++
786				case "ready":
787					current.Ready++
788				case "todo":
789					current.Todo++
790				}
791			}
792			counts[featureID] = current
793		}
794		return counts
795	}
796	
797	func countTasks(tasks []database.WorkspaceTask) domain.TaskCounts {
798		var counts domain.TaskCounts
799		for _, t := range tasks {
800			counts.Total++
801			if t.Status != nil {
802				switch *t.Status {
803				case "done":
804					counts.Done++
805				case "in_progress":
806					counts.InProgress++
807				case "blocked":
808					counts.Blocked++
809				case "ready":
810					counts.Ready++
811				case "todo":
812					counts.Todo++
813				}
814			}
815		}
816		return counts
817	}
818	
819	func parsePRRefs(prData, workspacePRData []byte, repo string) []domain.PullRequestRef {
820		var refs []domain.PullRequestRef
821	
822		var pr map[string]interface{}
823		if prData != nil {
824			if json.Unmarshal(prData, &pr) == nil {
825				if url, ok := pr["url"].(string); ok && url != "" {
826					status, _ := pr["status"].(string)
827					refs = append(refs, domain.PullRequestRef{
828						Label:  "Implementation PR",
829						URL:    url,
830						Status: status,
831						Repo:   repo,
832					})
833				}
834			}
835		}
836	
837		var wsPR map[string]interface{}
838		if workspacePRData != nil {
839			if json.Unmarshal(workspacePRData, &wsPR) == nil {
840				if url, ok := wsPR["url"].(string); ok && url != "" {
841					status, _ := wsPR["status"].(string)
842					refs = append(refs, domain.PullRequestRef{
843						Label:  "Workspace PR",
844						URL:    url,
845						Status: status,
846						Repo:   "management-repo",
847					})
848				}
849			}
850		}
851		return refs
852	}
853	
854	func derefStr(s *string) string {
855		if s == nil {
856			return ""
857		}
858		return *s
859	}
860	
861	func rawJSONOrNil(raw json.RawMessage) json.RawMessage {
862		if len(raw) == 0 || string(raw) == "null" || !json.Valid(raw) {
863			return nil
864		}
865		return raw
866	}
