func TestSync_Failure_NoCache_ReturnsSourceError(t *testing.T) {
	db := &testhelpers.FakeDB{} // no workspace in DB
	syncErr := domain.NewAdapterError(domain.ErrAdapterTimeout, "adapter timeout")
